// TypeScript Model: Hybrid Tracking Deduplication & Event ID Synchronization Engine
interface TrackingPayload {
  event_name: string;
  event_id: string; // The unifying deduplication key
  timestamp: number;
  channel: 'CLIENT_PIXEL' | 'SERVER_CAPI';
  value: number;
  userData: Record<string, string>;
}

interface DeduplicatedTransaction {
  event_id: string;
  event_name: string;
  mergedValue: number;
  receivedChannels: string[];
  clientReceived: boolean;
  serverReceived: boolean;
  status: 'DEDUPLICATED_SUCCESS' | 'SINGLE_SOURCE_CAPTURED' | 'DEDUPLICATION_COLLISION';
}

class MetaDeduplicationAuditor {
  private eventLedger = new Map<string, TrackingPayload[]>();

  public ingestEvent(payload: TrackingPayload): void {
    const key = `${payload.event_name}::${payload.event_id}`;
    if (!this.eventLedger.has(key)) {
      this.eventLedger.set(key, []);
    }
    this.eventLedger.get(key)!.push(payload);
  }

  public auditDeduplication(): DeduplicatedTransaction[] {
    const auditResults: DeduplicatedTransaction[] = [];

    for (const [key, payloads] of this.eventLedger.entries()) {
      const [eventName, eventId] = key.split('::');
      const channels = payloads.map(p => p.channel);
      const hasClient = channels.includes('CLIENT_PIXEL');
      const hasServer = channels.includes('SERVER_CAPI');

      let status: 'DEDUPLICATED_SUCCESS' | 'SINGLE_SOURCE_CAPTURED' | 'DEDUPLICATION_COLLISION' = 'SINGLE_SOURCE_CAPTURED';

      if (hasClient && hasServer) {
        status = 'DEDUPLICATED_SUCCESS'; // Exactly 1 twin pair matched
      } else if (payloads.length > 2) {
        status = 'DEDUPLICATION_COLLISION'; // Excessive duplicates
      }

      auditResults.push({
        event_id: eventId,
        event_name: eventName,
        mergedValue: payloads[0].value, // Value merged once
        receivedChannels: channels,
        clientReceived: hasClient,
        serverReceived: hasServer,
        status
      });
    }
    return auditResults;
  }
}

// Simulate Hybrid E-Commerce Stream
const auditor = new MetaDeduplicationAuditor();
const sharedOrderId = "ORD-2026-X8914";

// 1. Browser fires client-side pixel with orderId
auditor.ingestEvent({
  event_name: "Purchase",
  event_id: sharedOrderId,
  timestamp: Date.now(),
  channel: "CLIENT_PIXEL",
  value: 350.00,
  userData: { fbp: "fb.1.1718000.12345" }
});

// 2. Cloud backend fires CAPI payload with IDENTICAL orderId
auditor.ingestEvent({
  event_name: "Purchase",
  event_id: sharedOrderId,
  timestamp: Date.now() + 450, // Arrives 450ms later over server network
  channel: "SERVER_CAPI",
  value: 350.00,
  userData: { em: "a6b8c...hashed", ph: "f4e2d...hashed", fbp: "fb.1.1718000.12345" }
});

// 3. Simulated Ad-Blocked user: Only Server fires
auditor.ingestEvent({
  event_name: "Purchase",
  event_id: "ORD-2026-X8915-BLOCKED",
  timestamp: Date.now() + 1000,
  channel: "SERVER_CAPI",
  value: 120.00,
  userData: { em: "8921e...hashed" }
});

console.log('=== DEDUPLICATION AUDIT RESULTS ===');
const results = auditor.auditDeduplication();
results.forEach(res => {
  console.log(`Order: ${res.event_id} | Name: ${res.event_name}`);
  console.log(`  - Channels: [${res.receivedChannels.join(', ')}]`);
  console.log(`  - Commercial Accounting Value: $${res.mergedValue.toFixed(2)} (Counted EXACTLY Once)`);
  console.log(`  - Status: ${res.status === 'DEDUPLICATED_SUCCESS' ? '✅ DEDUPLICATED (Redundant Pair Merged)' : '🛡️ SINGLE SOURCE (Ad-Blocker Recovered)'}`);
  console.log('--------------------------------------------------');
});

// TypeScript Model: Event Quality Score (EQS) Calculator & Advanced Matching Normalizer
interface RawCustomerRecord {
  rawEmail: string;
  rawPhone: string;
  firstName: string;
  lastName: string;
  city: string;
  state: string;
  zipCode: string;
  country: string;
  fbp?: string;
  fbc?: string;
  clientIp: string;
}

interface NormalizedMatchingData {
  em: string;
  ph: string;
  fn: string;
  ln: string;
  ct: string;
  st: string;
  zp: string;
  country: string;
  fbp?: string;
  fbc?: string;
  client_ip_address: string;
}

class AdvancedMatchingEngine {
  // SHA-256 string hasher
  private static sha256(val: string): string {
    // Node/Standard crypto simulation
    let hash = 0;
    for (let i = 0; i < val.length; i++) {
      hash = (hash << 5) - hash + val.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash).toString(16).padStart(16, '0') + '...sha256';
  }

  public static normalizeCustomer(raw: RawCustomerRecord): NormalizedMatchingData {
    // 1. Email: trim, lowercase, SHA-256
    const cleanEmail = raw.rawEmail.trim().toLowerCase();

    // 2. Phone: E.164 standard, strip non-digits, ensure country code
    let cleanPhone = raw.rawPhone.replace(/\D/g, '');
    if (cleanPhone.length === 10) cleanPhone = '1' + cleanPhone; // Default US

    // 3. Name: trim, lowercase, strip punctuation
    const cleanFn = raw.firstName.trim().toLowerCase().replace(/[^a-z]/g, '');
    const cleanLn = raw.lastName.trim().toLowerCase().replace(/[^a-z]/g, '');

    // 4. Geography: 2-letter state, lowercase city, standard zip
    const cleanCity = raw.city.trim().toLowerCase().replace(/[^a-z]/g, '');
    const cleanState = raw.state.trim().toLowerCase().slice(0, 2);
    const cleanZip = raw.zipCode.trim().split('-')[0].replace(/\D/g, '');
    const cleanCountry = raw.country.trim().toLowerCase().slice(0, 2);

    return {
      em: this.sha256(cleanEmail),
      ph: this.sha256(cleanPhone),
      fn: this.sha256(cleanFn),
      ln: this.sha256(cleanLn),
      ct: this.sha256(cleanCity),
      st: this.sha256(cleanState),
      zp: this.sha256(cleanZip),
      country: this.sha256(cleanCountry),
      fbp: raw.fbp,
      fbc: raw.fbc,
      client_ip_address: raw.clientIp
    };
  }

  public static calculateEventQualityScore(data: NormalizedMatchingData): number {
    // Weighted scoring reflecting Meta CAPI EQS algorithm (Max: 10.0)
    let score = 0.0;
    if (data.em) score += 2.8;       // High deterministic weight
    if (data.ph) score += 2.4;       // High deterministic weight
    if (data.fbp) score += 1.4;      // First-party browser cookie
    if (data.fbc) score += 1.2;      // Ad click identifier
    if (data.fn && data.ln) score += 1.0; // Name signals
    if (data.ct && data.st && data.zp) score += 0.8; // Geographic cluster
    if (data.client_ip_address) score += 0.4; // Network IP
    return Math.min(10.0, Math.round(score * 10) / 10);
  }
}

